<template><section v-loading="loading" class="pdf-page"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p v-if="anchor&&!loading&&!error" role="status" class="ps-muted">{{highlights.length?`已定位 ${highlights.length} 处引用文本`:'当前页未匹配到引用文本，请人工核对原文与版本'}}</p><div ref="surface" class="pdf-surface" :style="{width:width+'px',height:height+'px'}"><canvas ref="canvas" aria-label="文档原页渲染"/><div class="pdf-text-layer" aria-label="文档文本"><span v-for="(item,index) in items" :key="index" :style="{left:item.left+'px',top:item.top+'px',height:item.height+'px',width:item.width+'px',fontSize:item.height+'px'}">{{item.text}}</span></div><mark v-for="(hit,index) in highlights" :key="index" class="pdf-highlight" :style="{left:hit.left+'px',top:hit.top+'px',height:hit.height+'px',width:hit.width+'px'}" :aria-label="`引用命中：${hit.text}`"/></div></section></template>
<script setup lang="ts">
import { nextTick,onBeforeUnmount,ref,watch } from 'vue'
import type { PDFDocumentLoadingTask,PDFDocumentProxy,PDFWorker,RenderTask } from 'pdfjs-dist'
import { errorText } from '../../composables/usePage'
import {LocalPdfBinaryDataFactory} from './pdfAssets'
const props=defineProps<{blob:Blob;zoom:number;anchor?:string}>()
const canvas=ref<HTMLCanvasElement>(),surface=ref<HTMLElement>(),loading=ref(false),error=ref(''),width=ref(0),height=ref(0),items=ref<Box[]>([]),highlights=ref<Box[]>([])
interface Box {text:string;left:number;top:number;width:number;height:number;start:number;end:number}
let pdf:PDFDocumentProxy|undefined,task:PDFDocumentLoadingTask|undefined,render:RenderTask|undefined,worker:PDFWorker|undefined,port:Worker|undefined,serial=0,renderSerial=0,disposed=false
const normalize=(value:string)=>value.replace(/\s+/g,' ').trim()
function cleanup(){serial++;renderSerial++;render?.cancel();render=undefined;void task?.destroy();task=undefined;pdf=undefined;worker?.destroy();worker=undefined;port?.terminate();port=undefined;items.value=[];highlights.value=[]}
async function load(){cleanup();const current=serial;loading.value=true;error.value='';try{const library=await import('pdfjs-dist');const workerAsset=await import('pdfjs-dist/build/pdf.worker.min.mjs?url');const bytes=await props.blob.arrayBuffer();if(current!==serial||disposed)return;port=new Worker(workerAsset.default,{type:'module'});worker=library.PDFWorker.create({port});task=library.getDocument({data:new Uint8Array(bytes),worker,disableAutoFetch:true,useWorkerFetch:false,BinaryDataFactory:LocalPdfBinaryDataFactory,maxImageSize:50000000});const document=await task.promise;if(current!==serial||disposed){await document.cleanup();return}pdf=document;await draw()}catch(e){if(current===serial&&!disposed)error.value=errorText(e)}finally{if(current===serial&&!disposed)loading.value=false}}
async function draw(){if(!pdf||!canvas.value)return;render?.cancel();const current=++renderSerial;loading.value=true;error.value='';try{const library=await import('pdfjs-dist');const page=await pdf.getPage(1);if(current!==renderSerial||disposed)return;const viewport=page.getViewport({scale:Math.max(0.5,Math.min(2,props.zoom/100))});width.value=viewport.width;height.value=viewport.height;const target=canvas.value;const ratio=Math.min(2,window.devicePixelRatio||1);target.width=Math.ceil(viewport.width*ratio);target.height=Math.ceil(viewport.height*ratio);target.style.width=viewport.width+'px';target.style.height=viewport.height+'px';const context=target.getContext('2d');if(!context)throw new Error('当前浏览器无法渲染 PDF 画布');render=page.render({canvas:target,canvasContext:context,viewport,transform:ratio===1?undefined:[ratio,0,0,ratio,0,0]});await render.promise;if(current!==renderSerial||disposed)return;const content=await page.getTextContent();if(current!==renderSerial||disposed)return;let offset=0;const boxes:Box[]=[];for(const item of content.items){if(!('str' in item))continue;const text=normalize(item.str);const transform=library.Util.transform(viewport.transform,item.transform);const fontHeight=Math.hypot(transform[2]!,transform[3]!);boxes.push({text,left:transform[4]!,top:transform[5]!-fontHeight,width:Math.max(1,item.width*viewport.scale),height:Math.max(1,fontHeight),start:offset,end:offset+text.length});offset+=text.length+1}items.value=boxes;locate();await nextTick();surface.value?.querySelector('mark')?.scrollIntoView({block:'center',inline:'nearest',behavior:'smooth'})}catch(e){if(current===renderSerial&&!disposed&&!(e instanceof Error&&e.name==='RenderingCancelledException'))error.value=errorText(e)}finally{if(current===renderSerial&&!disposed)loading.value=false}}
function locate(){const anchor=normalize(props.anchor||'').slice(0,160);if(!anchor){highlights.value=[];return}const text=items.value.map(item=>item.text).join(' ');const index=text.indexOf(anchor);highlights.value=index<0?[]:items.value.filter(item=>item.end>index&&item.start<index+anchor.length)}
watch(()=>props.blob,()=>void load(),{immediate:true});watch(()=>props.zoom,()=>void draw());watch(()=>props.anchor,locate)
onBeforeUnmount(()=>{disposed=true;cleanup()})
</script>
<style scoped>.pdf-page{min-height:300px;overflow:auto}.pdf-surface{position:relative;background:#fff;border:1px solid var(--el-border-color);margin:12px auto}.pdf-surface canvas{display:block}.pdf-text-layer{position:absolute;inset:0;overflow:hidden}.pdf-text-layer span{position:absolute;color:transparent;white-space:pre;line-height:1;transform-origin:left top;overflow:visible}.pdf-text-layer span::selection{background:rgba(64,158,255,.3)}.pdf-highlight{position:absolute;background:rgba(255,208,40,.35);outline:1px solid #e6a23c;pointer-events:none}</style>
